////////////////////////////////////\n\nmodel Goal {\n  id String @id @default(cuid())\n\n  title       String\n  description String?\n\n  priority GoalPriority @default(MEDIUM)\n\n  deadline DateTime?\n  status   GoalStatus @default(NOT_STARTED)\n  isActive Boolean    @default(true)\n\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  tasks Task[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//////////////////////////////////////////////////////\n// TASKS (PLANNING LAYER)\n//////////////////////////////////////////////////////\n\nmodel Task {\n  id String @id @default(cuid())\n\n  title       String\n  description String?\n\n  priority TaskPriority @default(MEDIUM)\n  status   TaskStatus   @default(PENDING)\n\n  estimatedMinutes Int\n  completedMinutes Int @default(0)\n\n  order Int?\n\n  userId String\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  goalId String?\n  goal   Goal?   @relation(fields: [goalId], references: [id], onDelete: SetNull)\n\n  timeBlocks TimeBlock[]\n  sessions   TaskSession[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//////////////////////////////////////////////////////\n// ROUTINES (REAL LIFE CONSTRAINTS)\n//////////////////////////////////////////////////////\n\nmodel Routine {\n  id String @id @default(cuid())\n\n  title       String\n  description String?\n\n  frequency RoutineFrequency\n\n  // e.g. \"Monday\", \"Tuesday\"\n  dayOfWeek Int?\n\n  startTime String\n  endTime   String\n\n  isActive Boolean @default(true)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//////////////////////////////////////////////////////\n// TIME BLOCKS (EXECUTION LAYER)\n//////////////////////////////////////////////////////\n\nmodel TimeBlock {\n  id String @id @default(cuid())\n\n  date DateTime\n\n  startTime DateTime\n  endTime   DateTime\n\n  type TimeBlockType\n\n  title String\n\n  completed Boolean @default(false)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  taskId String?\n  task   Task?   @relation(fields: [taskId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//////////////////////////////////////////////////////\n// TASK EXECUTION TRACKING\n//////////////////////////////////////////////////////\n\nmodel TaskSession {\n  id String @id @default(cuid())\n\n  taskId String\n  task   Task   @relation(fields: [taskId], references: [id], onDelete: Cascade)\n\n  startedAt DateTime\n  endedAt   DateTime?\n\n  duration  Int?\n  wasPaused Boolean @default(false)\n\n  createdAt DateTime @default(now())\n}\n\n//////////////////////////////////////////////////////\n// WEEKLY AVAILABILITY\n//////////////////////////////////////////////////////\n\nmodel Availability {\n  id String @id @default(cuid())\n\n  dayOfWeek Int\n\n  startTime String\n  endTime   String\n\n  isAvailable Boolean @default(true)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n//////////////////////////////////////////////////////\n// SETTINGS\n//////////////////////////////////////////////////////\n\nmodel Settings {\n  id String @id @default(cuid())\n\n  workHoursPerDay     Int @default(8)\n  breakMinutes        Int @default(15)\n  focusSessionMinutes Int @default(60)\n\n  theme String?\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n//////////////////////////////////////////////////////\n// AI MEMORY\n/////////